/**
 * agiter: the public API. Every client (the CLI, the sidecar for Far Manager, later an MCP
 * server) goes through these exports.
 */

export { loadDefs, lintDefs, PACKAGE_DEFS } from "./src/defs.mjs";
export { resolvePipeline, planRun, parseToken, tokenOf, pipelineText, REVIEW } from "./src/pipeline.mjs";
export { readDoc, readInput, validateDoc, parseReport, typeId, typeName } from "./src/artifacts.mjs";
export { parseFrontmatter, formatFrontmatter } from "./src/frontmatter.mjs";
export { acceptDocument, profileRun } from "./src/engine.mjs";
export { planScenario, startRun, continueRun, resumeRun, resumableRuns, pickRun, suffixOf, runLock, checkRun, checkRuns, finishRun, loadRun, listRuns, deleteRuns, readAudit, ISOLATION, ISOLATIONS, modeOf, docsDir } from "./src/engine.mjs";
export { fakeExecutor } from "./src/fake.mjs";
export { initProject, findProjectRoot, isProject } from "./src/init.mjs";
export { loadBlocks, readStack, writeStack, resolveSelection, composeStack, composeProject, projectDescription, projectStack, detectBlocks } from "./src/stack.mjs";
export { newProject, scaffoldOf, pkgSetCommand } from "./src/scaffold.mjs";
export { packagePlan, checkPackages, installPackages, installCommands, npmName } from "./src/packages.mjs";
export { resolveModels, lintModels, modelFiles, listModels } from "./src/models.mjs";
export { loadAgents, agentExecutor } from "./src/agents.mjs";

/** A greeting, for checking an installation and a client connection. */
export const hello = () => "hello";

/** The definitions of a project as plain data (for clients): { artifacts, tasks, problems }. */
export async function definitions({ root } = {}) {
	const { loadDefs } = await import("./src/defs.mjs");
	const defs = loadDefs(root ?? null);
	return { problems: defs.problems, artifacts: [...defs.artifacts.values()], tasks: [...defs.tasks.values()] };
}

/** The models of a project's tasks as plain data (for clients): { models: [{ task, author, reviewer }], problems }. */
export async function models({ root } = {}) {
	const [{ loadDefs }, { listModels, lintModels }] = await Promise.all([import("./src/defs.mjs"), import("./src/models.mjs")]);
	const defs = loadDefs(root ?? null);
	return { problems: [...defs.problems, ...lintModels(root ?? null, [...defs.tasks.keys()])], models: listModels(root ?? null, defs) };
}
export { resolveLang } from "./src/lang.mjs";
export { newDocument, listTemplates, templateOf } from "./src/templates.mjs";

#!/usr/bin/env node
/**
 * agiter: the command line, a thin layer over the API (index.mjs), parsed with commander.
 * `agiter --help` and `agiter <command> --help` list the commands and their options.
 * Exit codes: 0 done (or planned), 1 blocked, failed or invalid, 2 usage.
 */

import fs from "node:fs";
import { limitsText, money, tokens } from "../src/usage.mjs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { Command, CommanderError, Option } from "commander";
import * as api from "../index.mjs";
import { logCli } from "../src/log.mjs";

const USAGE = 2;

const tokenOf = api.tokenOf;

function printRun(run) {
	const where = !run.git ? "" : (run.git.mode ?? "branch") === "checkout" ? "  (no isolation: the checkout itself)" : `  (${run.git.mode === "worktree" ? `worktree ${run.git.worktree}, ` : ""}branch ${run.git.branch}${run.finished ? `, finished${run.finished.merged ? ", merged" : ""}` : ""})`;
	console.log(`run ${run.id}: ${run.status}${where}`);
	console.log(`  pipeline ${run.pipeline.steps.map(tokenOf).join(" ")}, input ${run.input.type}${run.lang ? `, output in ${run.lang}` : ""}`);
	for (const s of run.steps) {
		const what = s.outcome === "failed" ? `failed [${s.guard}] ${s.error}` : `${s.file ? path.posix.basename(s.file) : ""}${s.verdict ? ` ${s.verdict}` : ""}`;
		console.log(`  ${String(s.step).padEnd(3)} ${s.task.padEnd(13)} ${(s.round ? `r${s.round}` : "").padEnd(4)}${s.role.padEnd(9)} ${what}${s.usage ? `  ${money(s.usage)}` : ""}`);
	}
	if (run.steps.some((s) => s.executor === "model" || s.executor === "fake")) {
		const calls = run.steps.filter((s) => s.executor === "model");
		const missing = calls.filter((s) => !s.usage).length;
		console.log(`  cost: ${run.usage ? `${money(run.usage)} (${tokens(run.usage)})` : "no usage data"}${missing && run.usage ? `; ${missing} call(s) without usage data` : ""}`);
		if (run.limits) for (const [agent, l] of Object.entries(run.limits)) console.log(`  limits: ${agent} ${limitsText(l)} (used now; in brackets what this run added, an estimate)`);
	}
	if (run.decisions) {
		const d = run.decisions;
		console.log(`  decisions: ${d.owner ?? 0} for you${d.review ? `, ${d.review} open from the review` : ""}, ${(d.owner ?? 0) + (d.review ?? 0) + (d.unmarked ?? 0) + (d.author ?? 0)} in all -> ${d.file}`);
	}
	if (run.error) console.log(`  ${run.status} at step ${run.error.step} ${run.error.task}: ${run.error.message}\n  next: ${run.error.guard === "review" ? `comment the findings in ${run.decisions?.file ?? "the decisions report"} (or edit the input), then: agiter resume ${run.id}` : run.status === "blocked" && run.decisions?.file ? `answer in ${run.decisions.file}, then: agiter resume ${run.id}` : `agiter resume ${run.id}`}`);
	else if (run.status === "done" && run.git && (run.git.mode ?? "branch") !== "checkout" && !run.finished) console.log(`  next: agiter finish ${run.id} --merge (or without --merge to keep the branch)`);
	else if (run.status === "done" && run.git?.mode === "checkout") console.log("  next: review the changes (git status, git diff) and commit them");
}

const pad2 = (n) => String(n).padStart(2, "0");
/** A time in the machine's zone: yyyy-MM-dd HH:mm. */
const local = (iso) => { const d = new Date(iso); return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())} ${pad2(d.getHours())}:${pad2(d.getMinutes())}`; };
const duration = (s) => (s < 60 ? `${Math.round(s)} s` : s < 3600 ? `${Math.floor(s / 60)} min ${pad2(Math.round(s % 60))} s` : `${Math.floor(s / 3600)} h ${pad2(Math.floor((s % 3600) / 60))} min`);

/** The RegExp of a --list or --delete value (true: no pattern), or a usage error. */
function patternOf(value, option, cmd) {
	if (typeof value !== "string") return null;
	try { return new RegExp(value, "i"); } catch (e) { cmd.error(`error: --${option}: ${e.message}`, { exitCode: USAGE, code: "agiter.pattern" }); }
}

/** A run on one line: its id first (padded to `width`, the longest of the list), then when it started. */
const idWidth = (runs) => Math.max(0, ...runs.map((r) => r.id.length));
const runLine = (r, width = 0) => `${r.id.padEnd(width)}  ${local(r.created)}  ${r.status.padEnd(8)} ${duration(r.seconds).padStart(12)}  ${String(r.calls).padStart(3)} calls ${money(r.usage).padStart(9)}  ${r.pipeline}${r.name ? `  "${r.name}"` : ""}${r.finished ? (r.finished.merged ? "  merged" : "  finished") : ""}${r.replacedBy ? `  -> ${r.replacedBy}` : ""}${r.live ? "  (running now)" : ""}${r.error ? `  [${r.error}]` : ""}`;

/** run --list [pattern]: the runs, one per line. */
function listRunsOf(opts, cmd) {
	if (opts.failed || opts.done || opts.all || opts.yes) cmd.error(`error: options '--failed', '--done', '--all' and '--yes' belong to --delete`, { exitCode: USAGE, code: "agiter.delete" });
	const pattern = patternOf(opts.list, "list", cmd);
	const runs = api.listRuns(rootOf(opts), pattern, { order: opts.asc ? "asc" : "desc" });
	print(opts, runs, () => {
		for (const r of runs) console.log(runLine(r, idWidth(runs)));
		if (!runs.length) console.log(pattern ? `no run matches /${opts.list}/` : "no runs");
	});
}

/** Ask a yes/no question on the terminal. */
async function confirm(question) {
	const { createInterface } = await import("node:readline/promises");
	const rl = createInterface({ input: process.stdin, output: process.stdout });
	try { return /^y(es)?$/i.test((await rl.question(question)).trim()); } finally { rl.close(); }
}

/** run --delete --all [--yes]: every run and last.json, after two warnings. */
async function deleteAllOf(opts, cmd, root) {
	if (typeof opts.delete === "string" || opts.failed || opts.done) cmd.error("error: --all stands alone: no pattern, --failed or --done with it", { exitCode: USAGE, code: "agiter.all" });
	const runs = api.listRuns(root);
	const folders = fs.existsSync(path.join(root, "agiter", "runs")) ? fs.readdirSync(path.join(root, "agiter", "runs"), { withFileTypes: true }).filter((d) => d.isDirectory()).length : 0;
	if (!folders) { print(opts, { deleted: [] }, () => console.log("no run to delete")); return; }
	if (!opts.yes) {
		if (!process.stdin.isTTY) cmd.error(`error: --delete --all would delete all ${folders} run(s); confirm with --yes when the input is not a terminal`, { exitCode: USAGE, code: "agiter.confirm" });
		for (const r of runs) console.log(runLine(r, idWidth(runs)));
		if (folders > runs.length) console.log(`and ${folders - runs.length} broken run folder(s)`);
		console.log(`\nWARNING: this deletes ALL ${folders} run(s) of ${root}: their records, audits, logs of calls and every artifact they made. It cannot be undone.`);
		if (!(await confirm("Delete all runs? [y/N] "))) { console.log("nothing deleted"); process.exitCode = 1; return; }
		const { createInterface } = await import("node:readline/promises");
		const rl = createInterface({ input: process.stdin, output: process.stdout });
		let typed;
		try { typed = (await rl.question(`SECOND WARNING: type "delete all" to delete all ${folders} run(s): `)).trim(); } finally { rl.close(); }
		if (typed !== "delete all") { console.log("nothing deleted"); process.exitCode = 1; return; }
	}
	logCli(root, process.argv.slice(2));
	const { deleted, busy } = api.deleteRuns(root, { all: true });
	print(opts, { deleted, busy }, () => {
		console.log(`deleted ${busy.length ? "" : "all "}${deleted.length} run(s)${busy.length ? "" : "; last.json cleared"}`);
		if (busy.length) console.log(`not deleted, another agiter works on them now: ${busy.map((r) => r.id).join(", ")}`);
	});
}

/** run --delete [pattern] [--failed] [--done] [--yes]: delete runs, after showing them. */
async function deleteRunsOf(opts, cmd) {
	if (opts.asc || opts.desc) cmd.error(`error: options '--asc' and '--desc' belong to --list`, { exitCode: USAGE, code: "agiter.order" });
	const root = rootOf(opts);
	if (opts.all) return deleteAllOf(opts, cmd, root);
	const pattern = patternOf(opts.delete, "delete", cmd);
	const statuses = [...(opts.failed ? ["failed"] : []), ...(opts.done ? ["done"] : [])];
	if (!pattern && !statuses.length) {
		const all = api.listRuns(root);
		const message = "--delete needs a restriction: a pattern, --failed or --done (a pattern \".\" selects every run)";
		print(opts, { deleted: [], problems: [message], runs: all }, () => {
			console.log(`${message}. The runs:`);
			for (const r of all) console.log(`  ${runLine(r, idWidth(all))}`);
			if (!all.length) console.log("  no runs");
		});
		process.exitCode = USAGE;
		return;
	}
	const runs = api.listRuns(root, pattern).filter((r) => !statuses.length || statuses.includes(r.status));
	if (!runs.length) { print(opts, { deleted: [] }, () => console.log("no run to delete")); return; }
	if (!opts.yes) {
		if (!process.stdin.isTTY) cmd.error(`error: --delete would delete ${runs.length} run(s); confirm with --yes when the input is not a terminal`, { exitCode: USAGE, code: "agiter.confirm" });
		for (const r of runs) console.log(runLine(r, idWidth(runs)));
		if (!(await confirm(`Delete these ${runs.length} run(s) with their artifacts? This cannot be undone. [y/N] `))) { console.log("nothing deleted"); process.exitCode = 1; return; }
	}
	logCli(root, process.argv.slice(2));
	const { deleted, busy } = api.deleteRuns(root, { pattern, statuses });
	print(opts, { deleted, busy }, () => {
		console.log(`deleted ${deleted.length} run(s)${opts.yes ? `: ${deleted.map((r) => r.id).join(", ")}` : ""}`);
		if (busy.length) console.log(`not deleted, another agiter works on them now: ${busy.map((r) => r.id).join(", ")}`);
	});
}

const clockOf = (iso) => { const d = new Date(iso); return `${pad2(d.getHours())}:${pad2(d.getMinutes())}:${pad2(d.getSeconds())}`; };

/**
 * The live view of a run for the terminal: every event as it happens, and (unless quiet) the
 * agents' output as it comes, indented under the call. None with --json (the result is JSON).
 */
function live(opts) {
	if (opts.json) return {};
	let pending = "";
	const flush = () => { if (pending) { process.stdout.write(`    | ${pending}\n`); pending = ""; } };
	const onEvent = (e) => {
		flush();
		console.log(`${clockOf(e.at)}  ${e.event.padEnd(13)} ${e.detail}`);
	};
	const onOutput = opts.quiet ? undefined : ({ text }) => {
		const lines = (pending + text.replace(/\r\n?/g, "\n")).split("\n");
		pending = lines.pop();
		for (const l of lines) process.stdout.write(`    | ${l}\n`);
	};
	return { onEvent, onOutput, done: flush };
}

/** The --pipeline value: the shell may split an unquoted list ("a:2, b") into several items. */
const pipelineOf = (items) => [].concat(items).join(" ");

/** The git work tree's top of the current folder, or null. */
function gitTop() {
	const r = spawnSync("git", ["rev-parse", "--show-toplevel"], { encoding: "utf8", windowsHide: true });
	return r.status === 0 ? path.resolve(r.stdout.trim()) : null;
}

/** The project: --root, else found from the current folder (src/init.mjs findProjectRoot). */
const rootOf = (opts) => (opts.root ? path.resolve(opts.root) : api.findProjectRoot(process.cwd(), gitTop()));
const print = (opts, data, text) => { if (opts.json) console.log(JSON.stringify(data, null, "\t")); else text(); };
const problems = (opts, r) => { print(opts, r, () => r.problems.forEach((p) => console.log(`problem: ${p}`))); return 1; };

/** The options of a command that takes a scenario (`required`: --pipeline must be given). */
function scenario(cmd, required = true) {
	const pipeline = ["--pipeline <steps...>", "a pipeline file (*.json) or a list of tasks, apart by spaces or commas: task, task@profile (a profile of its model files), agent/task or agent/model/task; create-review[:N] after a task: at most N rounds of it with review (its own models: create-review@profile, agent/model/create-review); first in the pipeline: the input reviewed once"];
	return (required ? cmd.requiredOption(...pipeline) : cmd.option(...pipeline))
		.addOption(new Option("--input <file>", "the input file: prose, or an Active artifact").conflicts("text"))
		.addOption(new Option("--text <text>", "the input as text").conflicts("input"))
		.option("--id <id>", "the run's own id, after its stamp (<stamp>-<id>), and the name of what it makes; part of its identity: another id is another run (default: the input file's name; for text, each step's own heading)")
		.option("--lang <tag>", "the language of the output, an ISO tag: cs, en, cs-CZ, en-US, … (default: the language of the input); the headings the harness reads stay in English")
		.addOption(new Option("--isolation <mode>", "where the run works (over a pipeline file's isolation): checkout (the default: the current checkout itself, no harness commits), branch (a new branch agiter/<run> in this checkout, a commit per call) or worktree (a separate checkout in agiter/.worktrees/<run>); agiter isolation --list").choices(["checkout", "branch", "worktree"]))
		.option("--includeFile <file>", "a file every model call of the run gets whole in its prompt (repeat for more files); relative to the current folder, /<path> from the project's root", (v, prev) => [...prev, v], []);
}

const sampleText = (sample) => (!sample ? [] : [
	`sample ${sample.sample}: ${sample.input} (Active, ready to run)`,
	"next:",
	...sample.next.map((n) => `  ${n.command}\n      ${n.why}`),
]);
const common = (cmd) => cmd.option("--root <dir>", "the project (default: found from the current folder: the project it is in)").option("--json", "the result as JSON");

export function program() {
	const prog = new Command("agiter")
		.description("A harness for spec-driven agentic development.")
		.showHelpAfterError("(agiter --help, or agiter <command> --help)")
		.exitOverride();

	common(prog.command("init").description("make the current folder (or --root) an agiter project: agiter/ with the default config in agiter/config/ and project.md from a template")
		.option("--preset <id>", "a preset of the stack (see the list below): the stack's selection, the parts of project.md for its blocks and its packages declared in package.json")
		.option("--install", "with --preset: install the packages too (without it they are only declared: look at package.json, then agiter install)")
		.option("--exact", "with --preset: npm saves exact versions")
		.addHelpText("after", () => {
			const { presets } = api.loadBlocks(null);
			const width = Math.max(...[...presets.keys()].map((k) => k.length));
			return [
				"",
				"Examples:",
				"  agiter init                          agiter/ with the default config and project.md from the base template",
				"  agiter init --preset web-react-vite  the same, the stack set to React + Vite, project.md with its parts,",
				"                                       its packages declared in package.json (nothing installed yet)",
				"  agiter init --preset web-react-vite --install   and installed",
				"  agiter init --root ../app --preset web-angular",
				"",
				"init makes no project files (no entry page, no configuration): agiter new --preset does.",
				"",
				"Presets of the stack:",
				...[...presets.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([key, p]) => `  ${key.padEnd(width)}  ${p.alias ? `= ${p.id}` : `${p.title}${p.summary ? `: ${p.summary}` : ""}`}`),
				"",
				"Nothing that exists is overwritten. The stack can be changed later: agiter stack --help.",
			].join("\n");
		})).action((opts) => {
		// The current folder, unless it is already inside a project (then that project).
		const found = api.findProjectRoot(process.cwd());
		const root = opts.root ? path.resolve(opts.root) : api.isProject(found) ? found : process.cwd();
		if (opts.install && !opts.preset) { console.error("agiter: init: --install goes with --preset (agiter install installs the packages of a stack)"); process.exitCode = USAGE; return; }
		const r = api.initProject({ root, preset: opts.preset ?? null });
		if (r.problems?.length) { process.exitCode = problems(opts, r); return; }
		// The packages of the preset's blocks: declared in package.json (npm install --package-lock-only), installed with --install.
		if (r.preset) r.packages = api.installPackages({ root, lockOnly: !opts.install, exact: Boolean(opts.exact) });
		if (!opts.json && root !== process.cwd()) console.log(`project: ${root}`);
		print(opts, r, () => {
			for (const f of r.created) console.log(`created ${f}`);
			for (const f of r.existed) console
…[文件过长——中段 8KB 抽样]…
ut is not a terminal)")
		.addOption(new Option("--asc", "with --list: oldest first").conflicts(["desc"]))
		.addOption(new Option("--desc", "with --list: newest first (the default)").conflicts(["asc"]));
	common(run).action(async (opts, cmd) => {
		if (opts.list !== undefined) return listRunsOf(opts, cmd);
		if (opts.delete !== undefined) return deleteRunsOf(opts, cmd);
		for (const o of ["failed", "done", "all", "yes"]) if (opts[o]) cmd.error(`error: option '--${o}' belongs to --delete`, { exitCode: USAGE, code: "agiter.delete" });
		if (opts.asc || opts.desc) cmd.error(`error: option '--${opts.asc ? "asc" : "desc"}' belongs to --list`, { exitCode: USAGE, code: "agiter.order" });
		if (!opts.pipeline) cmd.error("error: required option '--pipeline <steps...>' not specified (or --list)", { exitCode: USAGE, code: "agiter.pipeline" });
		return runner(false)(opts);
	});
	common(runOptions(scenario(prog.command("simulate").description("run a scenario with a scripted fake model (in the project the current folder is in, or --root; outside a project in a new temporary one)")))
		.option("--script <file>", "what the fake model returns, per task, role and attempt")).action(runner(true));

	common(prog.command("resume").argument("[run]", "the run: its id, or the part after its stamp (its --id: the oldest such run that is not done); default: the oldest run that is not done").description("go on with a run that stopped: one its review blocked starts again as a new run with your comments (the same pipeline, input and --id); a failed or interrupted one goes on where it stopped")
		.option("--quiet", "show only the harness's events, not the agents' output")
		.option("--yes", "do not ask (needed when the input is not a terminal)")
		.addHelpText("after", [
			"",
			"Examples:",
			"  agiter resume                      the oldest run that is not done",
			"  agiter resume notefold             the oldest run notefold (its --id) that is not done",
			"  agiter resume 261117093012-notefold",
			"",
			"It shows the run it takes and asks first (the default is no). A run another agiter works on now is never taken.",
		].join("\n"))).action(async (id, opts, cmd) => {
		const root = rootOf(opts);
		logCli(root, process.argv.slice(2));
		const view = live(opts);
		if (root !== process.cwd() && !opts.json) console.log(`project: ${root}`);
		const picked = api.pickRun(root, id ?? null);
		if (picked.problems) { process.exitCode = problems(opts, { ok: false, problems: picked.problems }); return; }
		// Always confirmed (default no): a resume runs models, and a second one by mistake must not start anything.
		if (!opts.yes) {
			if (!process.stdin.isTTY) cmd.error(`error: resume would take run ${picked.id}; confirm with --yes when the input is not a terminal`, { exitCode: USAGE, code: "agiter.confirm" });
			const run = api.loadRun(root, picked.id);
			const how = run?.status === "blocked" && run.error?.guard === "review" ? "a new run with your comments (the same pipeline, input and --id)" : "it goes on where it stopped";
			console.log(`run ${picked.id}${picked.why ? ` (${picked.why})` : ""}: ${run?.status ?? "?"}${run?.error ? ` at step ${run.error.step} ${run.error.task}` : ""}`);
			if (!(await confirm(`Resume it: ${how}? [y/N] `))) { console.log("nothing resumed"); process.exitCode = 1; return; }
		} else if (!opts.json) console.log(`resume ${picked.id}${picked.why ? ` (${picked.why})` : ""}`);
		const r = await api.resumeRun({ root, run: picked.id, onEvent: view.onEvent, onOutput: view.onOutput });
		view.done?.();
		if (!r.ok) { process.exitCode = problems(opts, r); return; }
