				if (!r.missing.length && !r.misplaced.length && !r.versions.length && !r.scripts.missing.length && !r.problems.length) console.log(`package.json has every package the stack needs (${r.ok.length})`);
			});
			process.exitCode = r.missing.length || r.misplaced.length || r.versions.length || r.scripts.missing.length || r.problems.length ? 1 : 0;
			return;
		}
		const r = api.installPackages({ root, dryRun: Boolean(opts.dryRun), exact: Boolean(opts.exact), lockOnly: Boolean(opts.lockOnly) });
		print(opts, r, () => {
			if (r.problems.length && !r.commands.length) { report(r); return; }
			if (r.created) console.log(`${r.dryRun ? "would make" : "made"} package.json: ${JSON.stringify(r.created)}`);
			if (!r.commands.length) console.log("nothing to install: package.json has every package the stack needs");
			else {
				const declaredOnly = r.commands.includes("npm install") && !r.commands.some((c) => /^npm install --/.test(c));
				if (r.scripts.allowed.length) console.log(`${r.dryRun ? "would allow" : "allowed"} install scripts (allowScripts): ${r.scripts.allowed.join(", ")}`);
				if (r.installed.length || r.dryRun) console.log(r.dryRun ? (r.lockOnly ? "would declare:" : "would install:") : !r.ok ? "not installed (npm failed):" : r.lockOnly ? "declared in package.json (nothing installed):" : declaredOnly ? "installed what package.json declares:" : "installed:");
				for (const p of r.ok || r.dryRun ? r.installed : []) console.log(line(p));
				if (r.scripts.rebuilt.length) console.log(`ran their install scripts (npm rebuild): ${r.scripts.rebuilt.join(", ")}`);
				if (r.dryRun) for (const c of r.commands) console.log(`$ ${c}`);
