/** Run the command line `argv` (without node and the script); the exit code. */
export async function main(argv) {
	const prog = program();
	if (!argv.length) { prog.outputHelp(); return 0; }
	try {
		await prog.parseAsync(argv, { from: "user" });
		return process.exitCode ?? 0;
	} catch (e) {
		if (!(e instanceof CommanderError)) throw e;
		if (["commander.helpDisplayed", "commander.help", "commander.version"].includes(e.code)) return 0;
		if (e.code === "agiter.script") console.error(`agiter: ${e.message}`);
		return USAGE;
	}
}

